// Calling a plugin's vault: the signed native program that holds its secrets and performs the
// operations that need one (core/operations.json, `vault: true`). The protocol: `<vault> call
// <operation>`, the input as JSON on stdin; on stdout one JSON object, `{"output": ...}` or
// `{"error": {"id": "<declared error>", "variables": {...}}}`, with exit status 0 for both. Anything
// else is a failure of the vault itself. The caller turns the reply into text from its catalog.
import type { Io } from "./io";
import type { CallSignal } from "./operations";

export type VaultReply =
	| { readonly kind: "output"; readonly output: unknown }
	| { readonly kind: "error"; readonly id: string; readonly variables: Readonly<Record<string, string | number>> }
	/** The vault didn't answer by the protocol; `detail` is for logs, not the model. */
	| { readonly kind: "failed"; readonly detail: string };

const TIMEOUT_MS = 60_000;

function variables(value: unknown): Readonly<Record<string, string | number>> {
	if (typeof value !== "object" || value === null) return {};
	const out: Record<string, string | number> = {};
	for (const [k, v] of Object.entries(value)) if (typeof v === "string" || typeof v === "number") out[k] = v;
	return out;
}

/** The vault's reply to `stdout`, a run that exited 0. */
export function parseReply(stdout: string): VaultReply {
	let parsed: unknown;
	try {
		parsed = JSON.parse(stdout);
	} catch {
		return { kind: "failed", detail: `the vault's answer isn't JSON: ${stdout.slice(0, 200)}` };
	}
	if (typeof parsed !== "object" || parsed === null)
		return { kind: "failed", detail: "the vault's answer isn't an object" };
	if ("output" in parsed) return { kind: "output", output: parsed.output };
	const error: unknown = "error" in parsed ? parsed.error : undefined;
	if (typeof error === "object" && error !== null && "id" in error && typeof error.id === "string") {
		return { kind: "error", id: error.id, variables: variables("variables" in error ? error.variables : undefined) };
	}
	return { kind: "failed", detail: "the vault's answer has neither output nor error" };
}

/**
 * Where the plugin at `plugin` keeps its vault `program`: native/<program>, a starter that runs this
 * system's build, or native/<program>.exe on Windows (docs/manifests.md, "Native programs").
 */
export function vaultPath(plugin: string, program: string, windows: boolean): string {
	return windows ? `${plugin}\\native\\${program}.exe` : `${plugin}/native/${program}`;
}

/** One call of a vault: its operation, the input, and the signal of the call it serves. */
export interface VaultCall {
	readonly operation: string;
	readonly input: unknown;
	readonly signal?: CallSignal;
}

export async function callVault(io: Io, vault: string, call: VaultCall): Promise<VaultReply> {
	const run = await io.run([vault, "call", call.operation], {
		stdin: JSON.stringify(call.input),
		timeoutMs: TIMEOUT_MS,
		...(call.signal === undefined ? {} : { signal: call.signal }),
	});
	if (run.exitCode !== 0)
		return { kind: "failed", detail: `the vault exited ${run.exitCode}: ${run.stderr.slice(0, 500)}` };
	return parseReply(run.stdout);
}

files.../core/handlers.ts:
// The Kagi tools' handlers, the same in every shell: each sends its operation to the vault, which
// holds the session and talks to Kagi (cmd/kagi-vault), and turns the reply into what the model
// reads. `format` is the one argument the vault never sees: it picks the answer's form here.
import type { Io } from "../kit/core/io";
import type { CallSignal, Handlers, Outcome } from "../kit/core/operations";
import type { VaultReply } from "../kit/core/vault";
import { callVault } from "../kit/core/vault";
import { fieldsOf, isFields } from "./data";
import { errorText, kagiDown } from "./errors";
import { formatters } from "./format";
import { model } from "./model.gen";
import { operations } from "./operations.gen";

const FORMATS = ["markdown", "json"];

/** Where the vault is and how to run it. */
interface Vault {
	readonly io: Io;
	readonly path: string;
}

async function ask(vault: Vault, operation: string, input: unknown, signal?: CallSignal): Promise<VaultReply> {
	try {
		return await callVault(vault.io, vault.path, { operation, input, ...(signal ? { signal } : {}) });
	} catch (error) {
		return { kind: "failed", detail: error instanceof Error ? error.message : String(error) };
	}
}

function outcomeOf(operation: string, reply: VaultReply, json: boolean): Outcome {
	if (reply.kind === "error") return { ok: false, error: reply.id, text: errorText(reply.id, reply.variables) };
	if (reply.kind === "failed")
		return { ok: false, error: "vault", text: model.text("error-vault", { detail: reply.detail }) };
	const formatter = formatters[operation];
	const text =
		json || formatter === undefined
			? model.text("json", { json: JSON.stringify(reply.output) })
			: formatter(fieldsOf(reply.output));
	return { ok: true, text, data: reply.output };
}

async function perform(vault: Vault, operation: string, input: unknown, signal?: CallSignal): Promise<Outcome> {
	const { format, ...rest } = fieldsOf(input);
	if (format !== undefined && (typeof format !== "string" || !FORMATS.includes(format))) {
		const got = typeof format === "string" ? format : JSON.stringify(format);
		const variables = { name: "format", values: FORMATS.join(", "), got };
		return { ok: false, error: "one-of", text: errorText("one-of", variables) };
	}
	const reply = await ask(vault, operation, isFields(input) ? rest : input, signal);
	return outcomeOf(operation, reply, format === "json");
}

/**
 * A handler per Kagi tool, each calling the vault at `vault` through `io`, stopped when its call is
 * cancelled; `failed` hears of each outcome saying Kagi isn't working (kagiDown), for the "search"
 * setting.
 */
export function handlersFor(io: Io, vault: string, failed: () => void = () => undefined): Handlers {
	return Object.fromEntries(
		operations.tools.map(op => [
			op.id,
			async (input: unknown, signal?: CallSignal) => {
				const outcome = await perform({ io, path: vault }, op.id, input, signal);
				// A call cancelled midway stopped the vault; that says nothing about Kagi.
				if (kagiDown(outcome) && signal?.aborted !== true) failed();
				return outcome;
			},
		]),
	);
}

